      "rung": 2,
      "purpose": "Reset general fault latch when fault reset pushbutton is pressed."
    },
    {
      "rung": 3,
      "purpose": "Aggregate faults and E-stop loss into a single fault flag."
    },
    {
      "rung": 4,
      "purpose": "Energize conveyor motor contactor in auto mode when no faults are present."
    },
    {
      "rung": 5,
      "purpose": "Indicate pallet is in position when pallet at stop photo-eye is blocked."
    },
    {
      "rung": 6,
      "purpose": "Latch stopper release solenoid on rising edge of release request."
    },
    {
      "rung": 7,
      "purpose": "Run a 2-second timer while the stopper release solenoid is energized."
    },
    {
      "rung": 8,
      "purpose": "Unlatch the stopper release solenoid when the 2-second timer completes."
    },
    {
